'use strict';
const F=window.Finance;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-KZ',{maximumFractionDigits:0}).format(n)+' ₸';
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const currentMonth=localDate().slice(0,7);
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const accounts={kaspi:{name:'Kaspi Gold',color:'#cf5148',opening:190000},halyk:{name:'Halyk Bank',color:'#286f55',opening:240000},freedom:{name:'Freedom Bank',color:'#6d8b50',opening:110000},cash:{name:'Наличные',color:'#9b9079',opening:25000}};
const colors=['#355b44','#829a61','#bccb95','#d7ddb7','#b5b6a1','#b4c7ba','#d0a491','#9fb0ba','#aaa6bf','#d1c9af'];
const navItems=[['overview','Обзор','grid'],['transactions','Операции','arrows'],['banks','Мои банки','card'],['analytics','Аналитика','chart'],['budgets','Бюджеты','wallet'],['goals','Цели','target'],['family','Семейный бюджет','users'],['settings','Настройки','settings']];
const iconPaths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',arrows:'M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4',card:'M3 5h18v14H3z M3 10h18 M6 15h4',chart:'M4 3v17h17 M8 15l4-5 4 3 5-7',wallet:'M4 7h16v13H4z M4 7V4h13v3 M16 12h5v4h-5z',target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l9-9 M17 3h4v4',users:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-2a6 6 0 0 1 12 0v2 M17 5a4 4 0 0 1 0 8 M18 16a5 5 0 0 1 4 5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 4 4 1v7l-4 1-1 5H9l-1-5-5-1V8l5-1z'};
const svgIcon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.grid}"/></svg>`;
function seed(){
  const tx=[];
  const add=(month,day,merchant,amount,type,account)=>tx.push({id:uid(),date:month+'-'+String(day).padStart(2,'0'),merchant,amount,type,account,category:F.categorize(merchant,type),source:'demo'});
  const previous=new Date(currentMonth+'-15T12:00:00');previous.setMonth(previous.getMonth()-1);const prev=`${previous.getFullYear()}-${String(previous.getMonth()+1).padStart(2,'0')}`;
  for(const [month,factor] of [[prev,1.15],[currentMonth,1]]){
    const today=month===currentMonth?Number(localDate().slice(8)):28;
    add(month,1,'Зарплата',650000,'income','halyk');
    const list=[['Magnum',18450,'kaspi'],['Yandex Go',2450,'kaspi'],['Wolt • обед',6900,'freedom'],['SMALL',12800,'kaspi'],['Spotify',2190,'freedom'],['Аптека Europharma',8350,'halyk'],['Magnum',24600,'kaspi'],['Netflix',4590,'freedom'],['Yandex Go',1890,'kaspi'],['Кофейня',3600,'kaspi'],['Коммунальные услуги',32500,'halyk'],['Спортзал',22000,'freedom'],['Одежда',28500,'kaspi'],['Magnum',16300,'kaspi'],['Yandex Go',3100,'kaspi'],['Книги',8900,'freedom'],['Wolt • ужин',7800,'kaspi'],['SMALL',9300,'kaspi'],['Бензин',15000,'halyk'],['Кино',6500,'freedom'],['Magnum',19800,'kaspi'],['Yandex Go',2500,'kaspi'],['Кофейня',4200,'kaspi'],['Детский кружок',18000,'halyk']];
    list.forEach(([merchant,amount,account],i)=>{const day=1+(i%Math.max(1,today));add(month,day,merchant,Math.round(amount*factor),'expense',account);const t=tx[tx.length-1];if(merchant==='Кофейня')t.category='Рестораны';if(merchant==='Коммунальные услуги')t.category='Коммунальные платежи';if(merchant==='Одежда'||merchant==='Книги')t.category='Покупки';if(merchant==='Бензин')t.category='Автомобиль';if(merchant==='Кино')t.category='Развлечения';if(merchant==='Детский кружок')t.category='Дети';if(merchant==='Спортзал')t.category='Здоровье';});
    add(month,Math.min(2,today),'Перевод между своими счетами',50000,'transfer','kaspi');
    if(month===currentMonth)add(month,Math.min(3,today),'Фриланс • проект',85000,'income','freedom');
  }
  return {version:1,transactions:tx,rules:[],budgets:[{id:uid(),category:'Продукты',limit:120000},{id:uid(),category:'Рестораны',limit:25000},{id:uid(),category:'Транспорт',limit:20000}],goals:[{id:uid(),name:'Отпуск у моря',target:800000,saved:320000,emoji:'☀'},{id:uid(),name:'Финансовая подушка',target:1500000,saved:450000,emoji:'◈'}],members:[{id:uid(),name:'Я',role:'Владелец'},{id:uid(),name:'Александра',role:'Просмотр'}],theme:'light',privacy:false};
}
let storageAvailable=true,state;
try{const raw=localStorage.getItem('cashual-v1');state=raw?JSON.parse(raw):seed();if(state.version!==1||!Array.isArray(state.transactions)||!Array.isArray(state.budgets)||!Array.isArray(state.goals)||!Array.isArray(state.rules)||!Array.isArray(state.members))throw Error();}catch{state=seed();}
function persist(){try{localStorage.setItem('cashual-v1',JSON.stringify(state));}catch{storageAvailable=false;toast('Не удалось сохранить: проверьте свободное место и доступ к хранилищу.');}}
let page=navItems.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview',month=currentMonth,chartMode='bars';
let filters={query:'',type:'all',category:'all',account:'all'},modalAction=null;
function applyTheme(){document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('privacy-mask',state.privacy);}
function monthTransactions(m=month){return state.transactions.filter(t=>t.date.startsWith(m));}
function accountBalance(key){return accounts[key].opening+state.transactions.filter(t=>t.account===key).reduce((s,t)=>s+(t.type==='income'?t.amount:t.type==='expense'?-t.amount:0),0);}
function totalBalance(){return Object.keys(accounts).reduce((s,k)=>s+accountBalance(k),0);}
function categoryData(){const sum={};monthTransactions().filter(t=>t.type==='expense').forEach(t=>sum[t.category]=(sum[t.category]||0)+t.amount);return Object.entries(sum).sort((a,b)=>b[1]-a[1]);}
function spending(category){return monthTransactions().filter(t=>t.type==='expense'&&t.category===category).reduce((s,t)=>s+t.amount,0);}
function dateLabel(date){return new Intl.DateTimeFormat('ru',{day:'numeric',month:'short'}).format(new Date(date+'T12:00:00'));}
function monthLabel(m){return new Intl.DateTimeFormat('ru',{month:'long',year:'numeric'}).format(new Date(m+'-15T12:00:00')).replace(' г.','');}
function previousMonth(){const d=new Date(month+'-15T12:00:00');d.setMonth(d.getMonth()-1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
function monthPicker(){return `<input type="month" class="month-picker" id="month-picker" value="${esc(month)}" min="2000-01" max="2100-12" aria-label="Месяц отчёта">`;}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">Всё начинается с ясности</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,note,icon,featured=false){return `<div class="stat ${featured?'featured':''}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-number sensitive">${new Intl.NumberFormat('ru-KZ',{maximumFractionDigits:0}).format(value)} <span class="currency">₸</span></div><div class="stat-bottom">${note}</div></div>`;}
function stats(){const t=F.totals(monthTransactions()),limit=state.budgets.reduce((s,b)=>s+b.limit,0),budgetSpent=state.budgets.reduce((s,b)=>s+spending(b.category),0);return `<section class="stats" aria-label="Финансовая сводка">${stat('Общий баланс',totalBalance(),'Все демосчета и наличные','↗',true)}${stat('Доходы за месяц',t.income,'<span class="trend">↙</span> Поступления на ваши счета','↓')}${stat('Расходы за месяц',t.expense,'<span class="trend">↗</span> Без переводов между счетами','↑')}${stat('Остаток бюджета',limit-budgetSpent,'Лимиты выбранных категорий','◷')}</section>`;}
function chart(){
  const tx=monthTransactions(),days=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const weeks=Array.from({length:5},(_,i)=>({label:`${i*7+1}–${Math.min(days,(i+1)*7)}`,income:0,expense:0}));
  tx.forEach(t=>{const w=weeks[Math.min(4,Math.floor((Number(t.date.slice(8))-1)/7))];if(t.type==='income')w.income+=t.amount;if(t.type==='expense')w.expense+=t.amount;});
  const max=Math.max(10000,...weeks.flatMap(w=>[w.income,w.expense]));let content='';
  for(let i=0;i<4;i++){const y=16+i*47;content+=`<line x1="43" x2="540" y1="${y}" y2="${y}"/><text x="0" y="${y+3}">${Math.round(max*(1-i/3)/1000)}к</text>`;}
  weeks.forEach((w,i)=>{const x=76+i*100;content+=`<text x="${x+9}" y="183" text-anchor="middle">${w.label}</text>`;if(chartMode==='bars')content+=`<g><title>${w.label}: доходы ${money(w.income)}, расходы ${money(w.expense)}</title><rect x="${x-13}" y="${157-141*w.income/max}" width="19" height="${141*w.income/max}" rx="4" fill="#365d47"/><rect x="${x+11}" y="${157-141*w.expense/max}" width="19" height="${141*w.expense/max}" rx="4" fill="#c1d295"/></g>`;});
  if(chartMode==='lines')for(const [type,color] of [['income','#365d47'],['expense','#a5bd72']]){const points=weeks.map((w,i)=>`${85+i*100},${157-141*w[type]/max}`).join(' ');content+=`<polyline fill="none" stroke="${color}" stroke-width="3" stroke-linejoin="round" points="${points}"/>`;weeks.forEach((w,i)=>content+=`<circle cx="${85+i*100}" cy="${157-141*w[type]/max}" r="4" fill="${color}"><title>${w.label}: ${type==='income'?'доходы':'расходы'} ${money(w[type])}</title></circle>`);}
  return `<div class="chart-legend"><span><i class="legend-dot" style="background:#365d47"></i>Доходы</span><span><i class="legend-dot" style="background:#c1d295"></i>Расходы</span></div><div class="chart"><svg viewBox="0 0 550 196" role="img" aria-label="Доходы и расходы по неделям за ${esc(monthLabel(month))}">${content}</svg></div>`;
}
function chartPanel(){return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Движение денег</h2><p class="panel-subtitle">Доходы и расходы за ${esc(monthLabel(month))}</p></div><div class="segmented" aria-label="Вид графика"><button data-chart="bars" class="${chartMode==='bars'?'active':''}" aria-pressed="${chartMode==='bars'}">Столбцы</button><button data-chart="lines" class="${chartMode==='lines'?'active':''}" aria-pressed="${chartMode==='lines'}">Линии</button></div></div><div class="panel-body">${chart()}</div></section>`;}
function donutPanel(){const data=categoryData(),total=data.reduce((s,c)=>s+c[1],0);let top=data.slice(0,4);if(data.length>4)top.push(['Остальное',data.slice(4).reduce((s,c)=>s+c[1],0)]);let cursor=0;const stops=top.map(([_,v],i)=>{const start=cursor;cursor+=total?v/total*100:0;return `${colors[i]} ${start}% ${cursor}%`;});return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Куда уходят деньги</h2><p class="panel-subtitle">Расходы по категориям</p></div><span class="muted">◔</span></div><div class="panel-body"><div class="donut-area"><div class="donut" role="img" aria-label="Расходы по категориям: ${esc(top.map(([k,v])=>k+' '+money(v)).join(', '))}" style="background:${stops.length?'conic-gradient('+stops.join(',')+')':'var(--line)'}"><div class="donut-center"><span>Всего расходов</span><strong class="sensitive">${money(total)}</strong></div></div><div class="category-legend">${top.map(([name,value],i)=>`<div class="legend-row"><i class="legend-dot" style="background:${colors[i]}"></i><span>${esc(name)}</span><strong>${total?Math.round(value/total*100):0}%</strong></div>`).join('')||'<span class="muted">Нет расходов</span>'}</div></div></div><div class="panel-foot"><span>${data.length} категорий за месяц</span><button class="link-button" data-page="analytics">Подробнее ↗</button></div></section>`;}
function transactionRows(tx,editable=false){return tx.map(t=>`<tr><td><div class="merchant"><span class="merchant-icon" style="color:${t.type==='income'?'#3e8260':accounts[t.account]?.color||'#7e8c77'}">${t.type==='income'?'↓':t.type==='transfer'?'⇄':esc(t.merchant.slice(0,1).toUpperCase())}</span><div><strong>${esc(t.merchant)}</strong><small>${dateLabel(t.date)} · ${t.source==='demo'?'Демо':t.source==='import'?'Импорт':'Вручную'}</small></div></div></td><td>${editable&&t.type==='expense'?`<select class="table-select" data-category-id="${esc(t.id)}" aria-label="Категория для ${esc(t.merchant)}">${F.categories.map(c=>`<option ${c===t.category?'selected':''}>${esc(c)}</option>`).join('')}</select>`:`<span class="category-badge">${esc(t.category)}</span>`}</td><td><span class="bank-dot" style="background:${accounts[t.account]?.color}"></span>${accounts[t.account]?.name||'Наличные'}</td><td class="amount sensitive ${t.type}">${t.type==='income'?'+':t.type==='expense'?'−':''}${money(t.amount)}</td>${editable?`<td><button class="icon-button" data-delete-tx="${esc(t.id)}" aria-label="Удалить ${esc(t.merchant)}">×</button></td>`:''}</tr>`).join('');}
function table(tx,editable=false){return `<div class="table-wrap"><table><thead><tr><th>Операция</th><th>Категория</th><th>Счёт</th><th style="text-align:right">Сумма</th>${editable?'<th></th>':''}</tr></thead><tbody>${transactionRows(tx,editable)}</tbody></table>${tx.length?'':'<div class="empty">Операций пока нет. Добавьте вручную или импортируйте CSV.</div>'}</div>`;}
function budgetPreview(){return `<section class="panel budget-panel"><div class="panel-head"><h2 class="panel-title">В рамках бюджета</h2><button class="link-button" data-page="budgets">Все ↗</button></div><div class="panel-body"><div class="budget-list">${state.budgets.slice(0,3).map(b=>{const spent=spending(b.category),ratio=spent/b.limit;return `<div><div class="budget-label"><strong>${esc(b.category)}</strong><span class="sensitive">${money(spent)} / ${money(b.limit)}</span></div><div class="progress"><div style="width:${Math.min(100,ratio*100)}%;background:${ratio>1?'#c37d6f':ratio>.8?'#b0b77c':'#829b69'}"></div></div>${ratio>1?'<div class="budget-warning">Лимит превышен на '+money(spent-b.limit)+'</div>':''}</div>`;}).join('')||'<p class="muted">Создайте первый бюджет</p>'}</div></div></section>`;}
function goalPreview(){const g=state.goals[0];return `<section class="panel goal-panel"><div class="panel-head"><h2 class="panel-title">Ближе к мечте</h2><button class="link-button" data-page="goals">Все цели ↗</button></div><div class="panel-body">${g?`<div class="goal-preview"><span class="goal-icon">${esc(g.emoji)}</span><div><strong>${esc(g.name)}</strong><p class="sensitive">${money(g.saved)} из ${money(g.target)}</p><div class="progress"><div style="width:${Math.min(100,g.saved/g.target*100)}%"></div></div></div><span class="goal-percent">${Math.round(g.saved/g.target*100)}<small>%</small></span></div>`:'<p class="muted">Добавьте цель и начните копить</p>'}</div></section>`;}
function overview(){return heading('Деньги под контролем.','Ваша финансовая картина — в одном спокойном месте.',`${monthPicker()}<button class="button primary" data-action="new-transaction">＋ Добавить операцию</button>`)+`<div class="welcome-banner"><span class="sparkle">✧</span><span><strong>Добро пожаловать в Cashual.</strong> Здесь всё наглядно: от утреннего кофе до больших планов.</span><button class="text-button" data-page="banks">Мои счета ↗</button></div>`+stats()+`<div class="dashboard-grid">${chartPanel()}${donutPanel()}<section class="panel transaction-panel"><div class="panel-head"><div><h2 class="panel-title">Последние операции</h2><p class="panel-subtitle">Маленькие детали большой картины</p></div><button class="link-button" data-page="transactions">Все операции ↗</button></div>${table(monthTransactions().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6))}<div class="panel-foot"><span>✧ Категоризация по сохранённым правилам</span><span>Демоданные</span></div></section>${budgetPreview()}${goalPreview()}</div>`;}
function filteredTransactions(){return monthTransactions().filter(t=>(!filters.query||t.merchant.toLowerCase().includes(filters.query.toLowerCase()))&&(filters.type==='all'||t.type===filters.type)&&(filters.category==='all'||t.category===filters.category)&&(filters.account==='all'||t.account===filters.account)).sort((a,b)=>b.date.localeCompare(a.date));}
function transactions(){return heading('Каждая операция на виду.','Меняйте категории — Cashual запомнит правило для этого продавца.',`${monthPicker()}<button class="button secondary" data-action="import">↥ Импорт CSV</button><button class="button primary" data-action="new-transaction">＋ Операция</button>`)+`<section class="panel"><div class="panel-head"><h2 class="panel-title">История операций</h2><button class="link-button" data-action="export-csv">Экспорт CSV ↗</button></div><div class="filters"><input class="input search" id="search" placeholder="Поиск по названию…" value="${esc(filters.query)}" aria-label="Поиск операций"><select class="input" id="filter-type" aria-label="Тип операции">${[['all','Все типы'],['expense','Расходы'],['income','Доходы'],['transfer','Переводы']].map(([v,l])=>`<option value="${v}" ${filters.type===v?'selected':''}>${l}</option>`).join('')}</select><select class="input" id="filter-category" aria-label="Категория"><option value="all">Все категории</option>${[...F.categories,'Доходы','Переводы'].map(c=>`<option ${filters.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select class="input" id="filter-account" aria-label="Счёт"><option value="all">Все счета</option>${Object.entries(accounts).map(([k,a])=>`<option value="${k}" ${filters.account===k?'selected':''}>${a.name}</option>`).join('')}</select></div><div id="transactions-table">${table(filteredTransactions(),true)}</div><div class="panel-foot"><span id="tx-count">Найдено: ${filteredTransactions().length}</span><button class="link-button" data-action="csv-template">Скачать шаблон CSV</button></div></section><p class="notice">Переводы между своими счетами не включаются в доходы и расходы. В этой версии они фиксируются отдельно и не перемещают баланс между демосчетами.</p>`;}
function banks(){return heading('Все счета. Одно место.','Ваши демосчета и наличные — рядом.',`<button class="button secondary" data-action="import">↥ Импорт выписки</button><button class="button primary" data-action="bank-info">＋ Подключить банк</button>`)+`<div class="card-grid">${Object.entries(accounts).map(([key,a])=>`<article class="bank-card" style="background:${a.color}"><span class="bank-name">${a.name}</span><small>${key==='cash'?'Учёт наличных':'Демонстрационный счёт · KZT'}</small><div class="bank-balance sensitive">${money(accountBalance(key))}</div><span class="demo-label">${key==='cash'?'Ручной учёт':'Демо · не подключён к банку'}</span></article>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><h2 class="panel-title">Подключение без лишних рисков</h2></div><div class="panel-body"><div class="info-box"><strong>Реальные банковские API пока не подключены.</strong><br>Kaspi, Halyk и Freedom Bank показаны на демонстрационных данных. Для реальных интеграций нужны разрешённые банковские API и отдельный защищённый сервер. До этого используйте CSV-выписки или ручной ввод.<br>Cashual не запрашивает PIN, CVV и пароли интернет-банкинга.</div><p class="notice">Начальные демоостатки добавлены к операциям обоих демонстрационных месяцев. Переводы являются информационными записями.</p></div></section>`;}
function analytics(){const t=F.totals(monthTransactions()),p=F.totals(monthTransactions(previousMonth())),delta=p.expense?(t.expense-p.expense)/p.expense*100:null,data=categoryData();return heading('У денег есть история.','Замечайте привычки и принимайте решения с ясной головой.',monthPicker())+`<div class="analytics-grid">${chartPanel()}${donutPanel()}</div><div class="month-comparison section-gap"><section class="panel comparison-box"><h2 class="panel-title">Этот месяц</h2><strong class="sensitive">${money(t.expense)}</strong><p>${delta===null?'Для сравнения пока нет расходов за прошлый месяц.':`${Math.abs(delta).toFixed(1)}% ${delta>0?'больше':'меньше'} расходов, чем за ${esc(monthLabel(previousMonth()))}.`}</p><span class="muted" style="font-size:10px">Сравнение всех операций календарных месяцев</span></section><section class="panel comparison-box"><h2 class="panel-title">Остаётся от доходов</h2><strong class="sensitive">${money(t.income-t.expense)}</strong><p>${t.income?Math.round((t.income-t.expense)/t.income*100)+'% доходов остаётся после расходов.':'Добавьте доходы для расчёта.'}</p></section></div><section class="panel section-gap"><div class="panel-head"><h2 class="panel-title">Расходы по категориям</h2></div><div class="panel-body"><div class="budget-list">${data.map(([c,v],i)=>`<div><div class="budget-label"><strong>${esc(c)}</strong><span class="sensitive">${money(v)}</span></div><div class="progress"><div style="width:${t.expense?v/t.expense*100:0}%;background:${colors[i%colors.length]}"></div></div></div>`).join('')||'<div class="empty">В этом месяце пока нет расходов.</div>'}</div></div>${data.length?`<div class="insight">Самая большая категория — <strong>${esc(data[0][0])}</strong>: ${Math.round(data[0][1]/t.expense*100)}% расходов. Можно установить для неё лимит в разделе «Бюджеты».</div>`:''}</section>`;}
function budgets(){return heading('Планы, которые работают.','Месячные лимиты по категориям. Предупредим, если выйдете за рамки.',`${monthPicker()}<button class="button primary" data-action="new-budget">＋ Создать бюджет</button>`)+`<div class="card-grid">${state.budgets.map(b=>{const spent=spending(b.category),ratio=spent/b.limit;return `<article class="panel budget-card"><h3>${esc(b.category)}</h3><div class="big-value sensitive">${money(spent)}</div><p>из ${money(b.limit)} · ${Math.round(ratio*100)}% лимита</p><div class="progress"><div style="width:${Math.min(100,ratio*100)}%;background:${ratio>1?'#c47d70':'#829b69'}"></div></div><p class="${ratio>1?'danger-text':''}">${ratio>1?'Превышение: '+money(spent-b.limit):'Осталось '+money(b.limit-spent)}</p><button class="button secondary" data-edit-budget="${b.id}">Изменить лимит</button> <button class="icon-button" data-delete-budget="${b.id}" aria-label="Удалить бюджет ${esc(b.category)}">×</button></article>`;}).join('')||'<div class="panel empty">Создайте первый бюджет по категории.</div>'}</div>`;}
function goals(){return heading('Ваше большое «однажды».','Превратите мечту в план с понятным прогрессом.',`<button class="button primary" data-action="new-goal">＋ Добавить цель</button>`)+`<div class="card-grid">${state.goals.map(g=>`<article class="panel goal-card"><span class="goal-icon">${esc(g.emoji)}</span><h3>${esc(g.name)}</h3><div class="goal-amounts"><strong class="sensitive">${money(g.saved)}</strong><span class="muted">${money(g.target)}</span></div><div class="progress"><div style="width:${Math.min(100,g.saved/g.target*100)}%"></div></div><p>${g.saved>=g.target?'Цель достигнута — поздравляем!':`${Math.round(g.saved/g.target*100)}% уже есть · осталось ${money(g.target-g.saved)}`}</p><button class="button primary" data-fund-goal="${g.id}">＋ Пополнить</button> <button class="icon-button" data-delete-goal="${g.id}" aria-label="Удалить цель ${esc(g.name)}">×</button></article>`).join('')||'<div class="panel empty">Начните с первой цели.</div>'}</div><p class="notice">Накопления — отдельный трекер прогресса. Пополнение цели не списывает деньги с банковских счетов.</p>`;}
function family(){return heading('Общие планы сближают.','Посмотрите, как может выглядеть ваш семейный бюджет.',`<button class="button primary" data-action="new-member">＋ Добавить участника</button>`)+`<div class="welcome-banner"><span class="sparkle">♧</span><span><strong>Макет семейного доступа.</strong> Участники и роли сохраняются только в этом браузере. Приглашения и доступ с других устройств пока не работают.</span></div><section class="panel"><div class="panel-head"><h2 class="panel-title">Ваше пространство</h2><span class="muted">${state.members.length} участника</span></div>${state.members.map(m=>`<div class="settings-row"><div class="member"><span class="avatar">${esc(m.name.slice(0,1))}</span><div><strong>${esc(m.name)}</strong><small>${m.role==='Владелец'?'Управление пространством':'Демонстрационная роль'}</small></div></div>${m.role==='Владелец'?'<span class="category-badge">Владелец</span>':`<div><select class="input" data-member-role="${m.id}" aria-label="Роль ${esc(m.name)}"><option ${m.role==='Просмотр'?'selected':''}>Просмотр</option><option ${m.role==='Редактор'?'selected':''}>Редактор</option></select><button class="icon-button" data-delete-member="${m.id}" aria-label="Удалить участника">×</button></div>`}</div>`).join('')}</section><div class="info-box section-gap"><strong>Для совместной работы нужен сервер.</strong><br>Аутентификация, реальные приглашения, изоляция семей и проверка прав на сервере входят в следующий этап. Роли этого прототипа показывают интерфейс и не обеспечивают защиту данных.</div>`;}
function settings(){return heading('Всё по-вашему.','Оформление, категоризация и контроль над данными.')+`<section class="panel"><div class="panel-head"><h2 class="panel-title">Личное пространство</h2></div><div class="settings-row"><div><strong>Тёмная тема</strong><small>Комфортный просмотр вечером</small></div><input class="toggle" id="dark-toggle" type="checkbox" ${state.theme==='dark'?'checked':''} aria-label="Тёмная тема"></div><div class="settings-row"><div><strong>Скрывать суммы</strong><small>Размытие сумм на экране для приватного просмотра</small></div><input class="toggle" id="privacy-toggle" type="checkbox" ${state.privacy?'checked':''} aria-label="Скрывать суммы"></div><div class="settings-row"><div><strong>Резервная копия</strong><small>Экспорт и восстановление всех локальных данных в JSON</small></div><div><button class="button secondary" data-action="backup">Скачать</button> <button class="button secondary" data-action="restore">Восстановить</button></div></div><div class="settings-row"><div><strong>Управление данными</strong><small>Операции и настройки хранятся в localStorage этого браузера. Облачной синхронизации и авторизации нет.</small></div><button class="button danger" data-action="reset">Сбросить демо</button></div></section><section class="panel section-gap"><div class="panel-head"><div><h2 class="panel-title">Правила категоризации</h2><p class="panel-subtitle">Личные правила имеют приоритет над встроенными. ИИ-сервис пока не подключён.</p></div></div>${[...state.rules,...F.baseRules].map((r,i)=>`<div class="rule-row"><span>${esc(r.match)}</span><span>→ ${esc(r.category)}</span><span class="muted">${i<state.rules.length?'Ваше правило':'Встроенное'}</span>${i<state.rules.length?`<button class="icon-button" data-delete-rule="${i}" aria-label="Удалить правило">×</button>`:''}</div>`).join('')}</section><div class="info-box section-gap"><strong>Безопасность и банковские данные</strong><br>Не загружайте конфиденциальные выписки на общедоступном компьютере. Прототип не хранит банковские токены и не запрашивает PIN, CVV и пароли. Для промышленной версии нужны серверная авторизация, шифрование и разрешённые банковские интеграции.</div>`;}
function render(){applyTheme();$('#navigation').innerHTML=navItems.map(([id,name,icon])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''} title="${name}">${svgIcon(icon)}<span>${name}</span></button>`).join('');$('#breadcrumb').textContent=navItems.find(x=>x[0]===page)?.[1]||'Обзор';$('#page').innerHTML=({overview,transactions,banks,analytics,budgets,goals,family,settings}[page]||overview)();document.title=`${navItems.find(x=>x[0]===page)?.[1]} — Cashual`;}
function navigate(next){page=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function openModal(title,body,action,submit='Сохранить'){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-submit').textContent=submit;$('#form-error').textContent='';modalAction=action;$('#modal').showModal();}
const field=(label,html)=>`<label class="field">${label}${html}</label>`;
const options=(arr,selected)=>arr.map(c=>`<option ${c===selected?'selected':''}>${esc(c)}</option>`).join('');
function transactionModal(){openModal('Новая операция',field('Тип','<select class="input" name="type"><option value="expense">Расход</option><option value="income">Доход</option><option value="transfer">Перевод между своими счетами</option></select>')+field('Название / продавец','<input class="input" name="merchant" required maxlength="100" placeholder="Например, Magnum">')+field('Сумма, ₸','<input class="input" name="amount" type="number" min="0.01" max="1000000000" step="0.01" required placeholder="0">')+field('Дата',`<input class="input" type="date" name="date" value="${localDate()}" min="2000-01-01" max="2100-12-31" required>`)+field('Счёт',`<select class="input" name="account">${Object.entries(accounts).map(([k,a])=>`<option value="${k}">${a.name}</option>`).join('')}</select>`)+field('Категория','<select class="input" name="category"><option value="auto">Определить по правилам</option>'+options(F.categories)+'</select>')+'<p class="notice">Для переводов и доходов категория назначается автоматически. Переводы не меняют остатки демосчетов.</p>',data=>{const amount=Number(data.get('amount')),type=data.get('type'),merchant=data.get('merchant').trim(),date=data.get('date');if(!Number.isFinite(amount)||amount<=0||amount>1e9||!merchant)throw Error('Введите корректное название и сумму.');if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Выберите дату.');const chosen=data.get('category'),category=type==='expense'&&chosen!=='auto'?chosen:F.categorize(merchant,type,state.rules);state.transactions.push({id:uid(),date,merchant,amount,type,account:data.get('account'),category,source:'manual'});month=date.slice(0,7);toast('Операция добавлена');});}
function goalModal(){openModal('На что будем копить?',field('Название цели','<input class="input" name="name" required maxlength="60" placeholder="Например, путешествие">')+field('Нужно накопить, ₸','<input class="input" name="target" type="number" min="1" max="1000000000" step="1" required>')+field('Уже накоплено, ₸','<input class="input" name="saved" type="number" min="0" max="1000000000" step="1" value="0" required>'),data=>{const target=Number(data.get('target')),saved=Number(data.get('saved')),name=data.get('name').trim();if(!name||target<=0||saved<0||!Number.isFinite(target)||!Number.isFinite(saved))throw Error('Проверьте название и суммы.');state.goals.push({id:uid(),name,target,saved,emoji:'✧'});toast('Цель создана');});}
function budgetModal(id){const b=state.budgets.find(b=>b.id===id);openModal(b?'Изменить бюджет':'Новый бюджет',field('Категория',`<select class="input" name="category">${options(F.categories,b?.category)}</select>`)+field('Лимит на месяц, ₸',`<input class="input" name="limit" type="number" min="1" max="1000000000" step="1" required value="${b?.limit||''}">`),data=>{const category=data.get('category'),limit=Number(data.get('limit'));if(state.budgets.some(x=>x.category===category&&x.id!==id))throw Error('Для этой категории уже есть бюджет.');if(!Number.isFinite(limit)||limit<=0)throw Error('Введите положительный лимит.');if(b)Object.assign(b,{category,limit});else state.budgets.push({id:uid(),category,limit});toast('Бюджет сохранён');});}
function confirmModal(title,text,action,button='Подтвердить'){openModal(title,`<p class="muted" style="font-size:12px">${esc(text)}</p>`,action,button);}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvLine(row){return row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',');}
function exportCSV(){const tx=filteredTransactions();const content=[['date','merchant','amount','type','account','category'],...tx.map(t=>[t.date,t.merchant,t.amount,t.type,t.account,t.category])].map(csvLine).join('\r\n');download('cashual-'+month+'.csv','\uFEFF'+content,'text/csv;charset=utf-8');}
function notifications(){const alerts=state.budgets.map(b=>({b,s:spending(b.category)})).filter(x=>x.s>x.b.limit);openModal('Ваши уведомления',alerts.length?alerts.map(({b,s})=>`<div class="info-box"><strong>${esc(b.category)}: лимит превышен</strong><br>Расходы ${money(s)} при лимите ${money(b.limit)}.</div>`).join(''):'<div class="info-box">Все бюджеты в пределах лимитов. Вы отлично справляетесь!</div>',()=>{},'Понятно');}
const actions={
  'new-transaction':transactionModal,'new-goal':goalModal,'new-budget':()=>budgetModal(),
  'close-modal':()=>$('#modal').close(),theme:()=>{state.theme=state.theme==='dark'?'light':'dark';persist();applyTheme();},
  notifications,'bank-info':()=>openModal('Подключение банков',`<div class="info-box"><strong>Сейчас доступен демонстрационный режим.</strong><br>Реальные подключения Kaspi, Halyk и Freedom Bank появятся при наличии разрешённых API. Вы можете импортировать операции из CSV или добавить их вручную. Банковские пароли не нужны.</div>`,()=>{},'Понятно'),
  import:()=>openModal('Импорт операций CSV',`<div class="info-box">Столбцы: <strong>date, merchant, amount, type</strong>.<br>Необязательно: account, category.<br>Дата: YYYY-MM-DD. Тип: expense, income или transfer. Сумма положительная, разделитель — запятая или точка с запятой. Файл UTF-8, до 5 МБ.<br>Повторные операции с той же датой, продавцом, суммой, типом и счётом будут пропущены.</div><button class="button secondary" type="button" data-action="csv-template">↓ Скачать шаблон</button>`,()=>{$('#import-file').click();},'Выбрать файл'),
  'csv-template':()=>download('cashual-template.csv','\uFEFFdate,merchant,amount,type,account,category\r\n'+localDate()+',Magnum,4500,expense,kaspi,Продукты\r\n'+localDate()+',Зарплата,300000,income,halyk,Доходы\r\n'+localDate()+',Между своими счетами,10000,transfer,kaspi,Переводы','text/csv;charset=utf-8'),
  'export-csv':exportCSV,backup:()=>download('cashual-backup.json',JSON.stringify(state,null,2),'application/json'),
  restore:()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>5e6)throw Error('Файл больше 5 МБ.');const next=JSON.parse(await file.text());validateBackup(next);confirmModal('Восстановить копию?','Текущие локальные данные будут заменены содержимым этой резервной копии.',()=>{state=next;persist();toast('Резервная копия восстановлена');});}catch(e){toast('Не удалось восстановить: '+e.message);}};input.click();},
  reset:()=>confirmModal('Вернуть демоданные?','Все ваши локальные операции, цели, бюджеты и правила будут заменены. Сначала скачайте резервную копию, если хотите сохранить их.',()=>{state=seed();month=currentMonth;filters={query:'',type:'all',category:'all',account:'all'};toast('Демоданные восстановлены');},'Сбросить'),
  'new-member':()=>openModal('Участник демопространства',field('Имя','<input class="input" name="name" required maxlength="60">')+field('Роль','<select class="input" name="role"><option>Просмотр</option><option>Редактор</option></select>')+'<div class="info-box">Это локальный макет. Уведомления и приглашения не отправляются.</div>',data=>{const name=data.get('name').trim();if(!name)throw Error('Введите имя.');state.members.push({id:uid(),name,role:data.get('role')});toast('Участник добавлен в макет');})
};
function validateBackup(s){
  const finite=(n,min=0)=>typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=1e12;const str=v=>typeof v==='string'&&v.length>0&&v.length<=200;
  if(s?.version!==1||!['transactions','rules','budgets','goals','members'].every(k=>Array.isArray(s[k])&&s[k].length<=10000))throw Error('Неверный формат резервной копии.');
  if(!s.transactions.every(t=>str(t.id)&&str(t.merchant)&&/^\d{4}-\d{2}-\d{2}$/.test(t.date)&&!isNaN(Date.parse(t.date))&&finite(t.amount,0.01)&&['expense','income','transfer'].includes(t.type)&&Object.hasOwn(accounts,t.account)&&[...F.categories,'Доходы','Переводы'].includes(t.category)&&['demo','manual','import'].includes(t.source)))throw Error('Некорректные операции.');
  if(!s.rules.every(r=>str(r.match)&&F.categories.includes(r.category))||!s.budgets.every(b=>str(b.id)&&F.categories.includes(b.category)&&finite(b.limit,1))||!s.goals.every(g=>str(g.id)&&str(g.name)&&str(g.emoji)&&finite(g.target,1)&&finite(g.saved))||!s.members.every(m=>str(m.id)&&str(m.name)&&['Владелец','Просмотр','Редактор'].includes(m.role))||!['light','dark'].includes(s.theme)||typeof s.privacy!=='boolean')throw Error('Некорректные настройки.');
  for(const key of ['transactions','budgets','goals','members'])if(new Set(s[key].map(x=>x.id)).size!==s[key].length)throw Error('Повторяющиеся идентификаторы.');
  if(new Set(s.budgets.map(x=>x.category)).size!==s.budgets.length)throw Error('Повторяющиеся бюджеты.');
}
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.page){navigate(b.dataset.page);return;}
  if(b.dataset.action){actions[b.dataset.action]?.();return;}
  if(b.dataset.chart){chartMode=b.dataset.chart;render();return;}
  if(b.dataset.editBudget){budgetModal(b.dataset.editBudget);return;}
  if(b.dataset.fundGoal){const g=state.goals.find(g=>g.id===b.dataset.fundGoal);openModal('Ближе к цели: '+g.name,field('Добавить к накоплениям, ₸','<input class="input" name="amount" type="number" required min="1" max="1000000000" step="1">')+'<p class="notice">Обновится только прогресс цели. Деньги со счетов не списываются.</p>',data=>{const amount=Number(data.get('amount'));if(!Number.isFinite(amount)||amount<=0)throw Error('Введите положительную сумму.');g.saved+=amount;toast(g.saved>=g.target?'Цель достигнута!':'Накопления пополнены');});return;}
  const deletes=[['deleteTx','transactions','Удалить операцию?'],['deleteBudget','budgets','Удалить бюджет?'],['deleteGoal','goals','Удалить цель?'],['deleteMember','members','Удалить участника?']];
  for(const [attr,key,title] of deletes)if(b.dataset[attr]){confirmModal(title,'Запись будет удалена из локальных данных.',()=>{state[key]=state[key].filter(x=>x.id!==b.dataset[attr]);toast('Запись удалена');},'Удалить');return;}
  if(b.dataset.deleteRule!==undefined){state.rules.splice(Number(b.dataset.deleteRule),1);persist();render();toast('Правило удалено');}
});
$('#modal-form').addEventListener('submit',e=>{e.preventDefault();try{modalAction?.(new FormData(e.target));persist();$('#modal').close();render();}catch(error){$('#form-error').textContent=error.message;}});
document.addEventListener('change',e=>{
  const el=e.target;
  if(el.id==='month-picker'){if(/^\d{4}-\d{2}$/.test(el.value)){month=el.value;render();}return;}
  if(['filter-type','filter-category','filter-account'].includes(el.id)){filters[el.id.replace('filter-','')]=el.value;updateTransactionTable();return;}
  if(el.dataset.categoryId){const t=state.transactions.find(t=>t.id===el.dataset.categoryId),match=t.merchant.toLowerCase();t.category=el.value;state.rules=state.rules.filter(r=>r.match!==match);state.rules.unshift({match,category:el.value});persist();toast('Категория сохранена. Правило применится к новым операциям.');return;}
  if(el.dataset.memberRole){state.members.find(m=>m.id===el.dataset.memberRole).role=el.value;persist();toast('Демонстрационная роль изменена');return;}
  if(el.id==='dark-toggle'){state.theme=el.checked?'dark':'light';persist();applyTheme();}
  if(el.id==='privacy-toggle'){state.privacy=el.checked;persist();applyTheme();}
});
function updateTransactionTable(){$('#transactions-table').innerHTML=table(filteredTransactions(),true);$('#tx-count').textContent='Найдено: '+filteredTransactions().length;}
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.query=e.target.value;updateTransactionTable();}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Файл больше 5 МБ.');const imported=F.parseCSV(await file.text(),state.rules);const key=t=>[t.date,t.merchant,t.amount,t.type,t.account].join('|');const seen=new Set(state.transactions.map(key));let count=0;for(const t of imported){if(!seen.has(key(t))){state.transactions.push({...t,id:uid()});seen.add(key(t));count++;}}persist();if(count)month=imported[0].date.slice(0,7);navigate('transactions');toast(`Импортировано: ${count}. Пропущено повторов: ${imported.length-count}.`);}catch(error){toast(error.message);}finally{e.target.value='';}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(navItems.some(x=>x[0]===next)&&next!==page){page=next;render();}});
applyTheme();render();persist();
